import math

def otherside_rightangle(a, b):
    """
    Function to calculate the third side of a right-angled triangle given two sides.
    If both sides are legs, calculate the hypotenuse.
    If one side is the hypotenuse, calculate the other leg.
    """
    if a > b:
        # `a` is the hypotenuse, calculate the other leg
        return math.sqrt(a**2 - b**2)
    elif b > a:
        # `b` is the hypotenuse, calculate the other leg
        return math.sqrt(b**2 - a**2)
    else:
        # Both sides are legs, calculate the hypotenuse
        return math.sqrt(a**2 + b**2)

