import math
from functools import lru_cache

def count_binary_seq(n):
    @lru_cache(None)
    def count_sequences(n, balance):
        # Base case: if no bits left and balance is zero, it's a valid sequence
        if n == 0:
            return 1 if balance == 0 else 0

        # Recursive case: For each bit position, calculate the balance
        # You can add 1 to the first half, or add 1 to the last half
        return count_sequences(n - 1, balance + 1) + count_sequences(n - 1, balance - 1)

    # Start with n bits for each half and an initial balance of 0
    return count_sequences(n, 0)

# Example tests
