def is_polite(num):
    """Helper function to determine if a number is polite."""
    if num <= 0:
        return False
    # A polite number is any number that is NOT a power of 2
    return (num & (num - 1)) != 0

def nth_polite_number(n):
    """Function to find the nth polite number."""
    count = 0
    current = 1
    while True:
        if is_polite(current):
            count += 1
            if count == n:
                return current
        current += 1

