def merge_dictionaries_three(dict1, dict2, dict3):
    # Merge dictionaries while ensuring values from later dictionaries overwrite earlier ones
    merged_dict = {}
    for d in [dict1, dict2, dict3]:  # Iterate through all dictionaries
        merged_dict.update(d)  # Update the merged dictionary with current dictionary
    return merged_dict

